#include <algorithm>
#include <fstream>
#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;
class Person{protected:int id;string name,contact;public:Person(int i,string n,string c):id(i),name(move(n)),contact(move(c)){}virtual~Person()=default;int getId()const{return id;}const string&getName()const{return name;}virtual void show()const{cout<<id<<" | "<<name<<" | "<<contact;}};
struct MembershipPlan{int id;string name;double monthlyFee;string access;};struct Attendance{int memberId;string date,inTime,outTime;};struct DuesRecord{int memberId;double amount;string month,status;};
class Member:public Person{int planId=0,trainerId=0;bool active=true;public:using Person::Person;int plan()const{return planId;}int trainer()const{return trainerId;}void setPlan(int p){planId=p;active=true;}void setTrainer(int t){trainerId=t;}bool isActive()const{return active;}void show()const override{Person::show();cout<<" | plan "<<planId<<" | trainer "<<trainerId<<" | "<<(active?"Active":"Expired")<<'\n';}};
class Trainer:public Person{string specialty;vector<int>members;public:Trainer(int i,string n,string c,string s):Person(i,move(n),move(c)),specialty(move(s)){}bool assign(int mid){if(find(members.begin(),members.end(),mid)!=members.end()||members.size()>=10)return false;members.push_back(mid);return true;}size_t load()const{return members.size();}void show()const override{Person::show();cout<<" | "<<specialty<<" | members "<<members.size()<<'\n';}};
class Gym{vector<Member>members;vector<Trainer>trainers;vector<MembershipPlan>plans{{1,"Basic",500,"Gym"},{2,"Premium",1200,"Gym+Classes"},{3,"VIP",2500,"All Access"}};vector<Attendance>attendance;vector<DuesRecord>dues;Member*m(int id){for(auto&x:members)if(x.getId()==id)return&x;return nullptr;}Trainer*t(int id){for(auto&x:trainers)if(x.getId()==id)return&x;return nullptr;}public:void addMember(){int id;string n,c;cout<<"ID: ";cin>>id;cout<<"Name: ";cin>>ws;getline(cin,n);cout<<"Contact: ";getline(cin,c);if(!m(id))members.emplace_back(id,n,c);}void addTrainer(){int id;string n,c,s;cout<<"ID: ";cin>>id;cout<<"Name: ";cin>>ws;getline(cin,n);cout<<"Contact: ";getline(cin,c);cout<<"Specialty: ";getline(cin,s);if(!t(id))trainers.emplace_back(id,n,c,s);}void assignPlan(){int mid,pid;cout<<"Member ID Plan ID: ";cin>>mid>>pid;if(auto*x=m(mid))x->setPlan(pid);}void assignTrainer(){int mid,tid;cout<<"Member ID Trainer ID: ";cin>>mid>>tid;auto*x=m(mid);auto*y=t(tid);if(x&&y&&y->assign(mid))x->setTrainer(tid);else cout<<"Invalid or trainer full\n";}void recordDues(){int mid;double amount;string month,status;cout<<"Member ID amount month status: ";cin>>mid>>amount>>month>>status;if(m(mid)&&amount>=0)dues.push_back({mid,amount,month,status});}void checkin(){int id;string d,time;cout<<"Member ID date time: ";cin>>id>>d>>time;if(auto*x=m(id);x&&x->isActive()){for(auto&a:attendance)if(a.memberId==id&&a.date==d&&a.outTime.empty()){cout<<"Already checked in\n";return;}attendance.push_back({id,d,time,""});}}void checkout(){int id;string d,time;cout<<"Member ID date time: ";cin>>id>>d>>time;for(auto&a:attendance)if(a.memberId==id&&a.date==d&&a.outTime.empty()){a.outTime=time;return;}}void list()const{cout<<"Members\n";for(auto&m:members)m.show();cout<<"Trainers\n";for(auto&t:trainers)t.show();cout<<"Plans\n";for(auto&p:plans)cout<<p.id<<" | "<<p.name<<" | fee "<<p.monthlyFee<<" | "<<p.access<<'\n';}void report()const{double recorded=0;for(auto&d:dues)if(d.status=="Recorded")recorded+=d.amount;cout<<"Members "<<members.size()<<" | recorded dues "<<recorded<<" | attendance "<<attendance.size()<<'\n';vector<pair<int,size_t>>rank;for(auto&t:trainers)rank.push_back({t.getId(),t.load()});sort(rank.begin(),rank.end(),[](auto&a,auto&b){return a.second>b.second;});for(auto&r:rank)cout<<"Trainer "<<r.first<<" -> "<<r.second<<" members\n";}void save()const{ofstream o("gym_members.txt");for(auto&x:members)o<<x.getId()<<'|'<<x.getName()<<'|'<<x.plan()<<'|'<<x.trainer()<<'\n';ofstream a("gym_attendance.txt");for(auto&x:attendance)a<<x.memberId<<'|'<<x.date<<'|'<<x.inTime<<'|'<<x.outTime<<'\n';}void run(){for(;;){cout<<"\nGym Management\n1 Add member 2 Add trainer 3 Assign plan 4 Assign trainer 5 Record membership dues 6 Check-in 7 Check-out 8 List 9 Reports 0 Exit\nChoice: ";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)addMember();else if(c==2)addTrainer();else if(c==3)assignPlan();else if(c==4)assignTrainer();else if(c==5)recordDues();else if(c==6)checkin();else if(c==7)checkout();else if(c==8)list();else if(c==9)report();}}};int main(){Gym{}.run();}
